<section class="container page-heading"><span class="section-kicker">Katalog</span><h1>Kelola layanan</h1><p>Atur layanan satuan yang dapat dihubungkan ke dalam paket foto. Layanan yang sudah dipakai dinonaktifkan, bukan dihapus, agar riwayat tetap utuh.</p></section>
<section class="container admin-page"><div class="row g-4 align-items-start"><div class="col-lg-4"><div class="surface surface-pad"><h2 class="h5 mb-4"><?= $editing ? 'Ubah layanan' : 'Tambah layanan' ?></h2><form method="post" action="<?= e(url('admin-services')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id_layanan" value="<?= (int) ($editing['id_layanan'] ?? 0) ?>"><div class="mb-3"><label class="form-label" for="nama_layanan">Nama layanan</label><input class="form-control" id="nama_layanan" name="nama_layanan" maxlength="100" required value="<?= e($editing['nama_layanan'] ?? '') ?>" placeholder="Contoh: Cetak foto 4R"></div><div class="mb-3"><label class="form-label" for="deskripsi">Deskripsi</label><textarea class="form-control" id="deskripsi" name="deskripsi" rows="3"><?= e($editing['deskripsi'] ?? '') ?></textarea></div><div class="mb-4"><label class="form-label" for="harga_satuan">Harga satuan (Rp)</label><input class="form-control" id="harga_satuan" type="number" name="harga_satuan" min="0" step="1000" required value="<?= e($editing['harga_satuan'] ?? '0') ?>"></div><button class="btn btn-copper w-100" type="submit">Simpan Layanan</button><?php if ($editing): ?> <a class="btn btn-link w-100 mt-2" href="<?= e(url('admin-services')) ?>">Batal mengubah</a><?php endif; ?></form></div></div><div class="col-lg-8"><div class="surface"><div class="surface-pad"><h2 class="h5 mb-1">Daftar layanan</h2><p class="form-note mb-0">Harga satuan dicatat sebagai informasi layanan.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Layanan</th><th>Harga</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($services as $service): ?><tr><td><strong><?= e($service['nama_layanan']) ?></strong><span class="subtext"><?= e($service['deskripsi']) ?></span></td><td><?= money($service['harga_satuan']) ?></td><td><span class="badge-status <?= $service['aktif']?'success':'secondary' ?>"><?= $service['aktif']?'Aktif':'Nonaktif' ?></span></td><td><div class="small-actions"><a class="btn btn-sm btn-outline-dark" href="<?= e(url('admin-services',['edit'=>$service['id_layanan']])) ?>">Ubah</a><form method="post" action="<?= e(url('admin-services')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id_layanan" value="<?= (int)$service['id_layanan'] ?>"><input type="hidden" name="active" value="<?= $service['aktif']?'0':'1' ?>"><button class="btn btn-sm <?= $service['aktif']?'btn-outline-danger':'btn-outline-success' ?>" data-confirm="<?= $service['aktif']?'Nonaktifkan':'Aktifkan' ?> layanan ini?" type="submit"><?= $service['aktif']?'Nonaktifkan':'Aktifkan' ?></button></form></div></td></tr><?php endforeach; ?><?php if (!$services): ?><tr><td colspan="4" class="muted text-center py-4">Belum ada layanan.</td></tr><?php endif; ?></tbody></table></div></div></div></div></section>
